/* ============================================================================
   VISITAS_SERVICIO_1  (28/10/2026)  marca VIS_SRV_V1  -- requiere PESTANIA_VISITAS y PLAN_DESARROLLO_5B aplicados
   ----------------------------------------------------------------------------
   Pestania Visitas de la V360 del proyecto (opcion A de boceto_visitas_servicios.html):
   - Chips por tipo de servicio (Todos / Consultoria / Auditorias / Capacitaciones) con la cantidad de visitas.
   - Filtro "Servicio" en la barra de la grilla (cada consultoria, auditoria o capacitacion) y, al elegir uno,
     su resumen (horas, visitas, desarrollo y sin detallar). La grilla sigue con 10 registros por pagina.
   - Columna "Desarrollos" (horas y registros realizados o planificados; clic: Trabajo de la visita).
   - Vista "Desarrollo" junto a Lista y Calendario: lo realizado y lo planificado en las visitas de la consultoria,
     con indicadores, filtros (tipo, consultor, servicio), buscador y Excel / PDF.
   - Assets: vct-proyecto-v360.css ?v=48 y vct-proyecto-v360.js ?v=40 (subir los dos archivos).
   Si alguno de los puntos no se encuentra (o esta repetido), NO se cambia nada. Re-ejecutable.  SSMS: F5.
   ============================================================================ */
USE [MuhlePROD];
SET NOCOUNT ON;
GO
DECLARE @D NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID('dbo.VCT_MAIN_PROYECTO_V360')), @NE NVARCHAR(MAX), @RE NVARCHAR(MAX), @i INT, @F NVARCHAR(MAX) = N'', @s INT, @p INT;
IF @D IS NULL
    PRINT 'FALLO: no se encontro dbo.VCT_MAIN_PROYECTO_V360.';
ELSE IF CHARINDEX(N'VIS_SRV_V1', @D) > 0
    PRINT 'OK   el parche VIS_SRV_V1 ya estaba aplicado: no se hizo nada.';
ELSE IF CHARINDEX(N'<span>Visitas</span></button>', @D) = 0
    PRINT 'FALLO: falta aplicar antes PESTANIA_VISITAS.sql. No se cambio nada.';
ELSE IF CHARINDEX(N'PL_DES_V5: trabajo de la visita', @D) = 0
    PRINT 'FALLO: falta aplicar antes PLAN_DESARROLLO_5B.sql. No se cambio nada.';
ELSE
BEGIN
    SET @D = REPLACE(@D, NCHAR(13) + NCHAR(10), NCHAR(10));
    /* calc */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'    SET @AG_H = CONVERT(VARCHAR(MAX), '''')' + NCHAR(10);
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'    /* VIS_SRV_V1: pestania Visitas: chips por tipo de servicio, filtro Servicio (cada consultoria / auditoria / capacitacion)' + NCHAR(10) + N'       con su resumen, columna Desarrollos y vista Desarrollo (lo realizado y planificado en las visitas de la consultoria) */' + NCHAR(10) + N'    DECLARE @AG_FINST VARCHAR(MAX) = '''', @AG_CHIPS VARCHAR(MAX) = '''', @AG_DES_H VARCHAR(MAX) = '''', @AG_DES_ROWS VARCHAR(MAX) = '''', @AG_DES_N INT = 0, @AG_DES_ON BIT = 0,' + NCHAR(10) + N'            @AG_DCONS VARCHAR(MAX) = '''', @AG_DINST VARCHAR(MAX) = '''', @AG_DINST_N INT = 0, @AG_DHV NUMERIC(18,2) = 0, @AG_DHR NUMERIC(18,2) = 0, @AG_DNP INT = 0,' + NCHAR(10) + N'            @AG_DNV INT = 0, @AG_DNVD INT = 0, @AG_DPROX DATETIME,' + NCHAR(10) + N'            @AG_IC_D VARCHAR(400) = ''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>'';' + NCHAR(10) + N'    IF EXISTS (SELECT 1 FROM #SV WHERE LEFT(COD, 2) = ''CO'') AND OBJECT_ID(''dbo.VCT_ACCIONES_DESARROLLO'', ''U'') IS NOT NULL SET @AG_DES_ON = 1;' + NCHAR(10) + N'    SELECT @AG_FINST = ISNULL((' + NCHAR(10) + N'        SELECT ''<option value="'' + CONVERT(VARCHAR(20), S.ID) + ''" data-t="'' + LOWER(LEFT(S.COD, 2)) + ''"''' + NCHAR(10) + N'             + '' data-ini="'' + ISNULL(CONVERT(VARCHAR(10), S.INI, 103), '''') + ''" data-fin="'' + ISNULL(CONVERT(VARCHAR(10), S.FIN, 103), '''') + ''"''' + NCHAR(10) + N'             + '' data-proy="'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(S.PROY, 0))), ''.0'', '''') + ''" data-ejec="'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(X.E, 0))), ''.0'', '''') + ''" data-prog="'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(X.P, 0))), ''.0'', '''') + ''"''' + NCHAR(10) + N'             + '' data-nv="'' + CONVERT(VARCHAR(10), ISNULL(X.N, 0)) + ''" data-ne="'' + CONVERT(VARCHAR(10), ISNULL(X.NE, 0)) + ''" data-nc="'' + CONVERT(VARCHAR(10), ISNULL(X.NC, 0)) + ''" data-np="'' + CONVERT(VARCHAR(10), ISNULL(X.NPE, 0)) + ''"''' + NCHAR(10) + N'             + '' data-dh="'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(DV.H, 0))), ''.0'', '''') + ''" data-dr="'' + CONVERT(VARCHAR(10), ISNULL(DV.NR, 0)) + ''" data-dp="'' + CONVERT(VARCHAR(10), ISNULL(DV.NP, 0)) + ''">''' + NCHAR(10) + N'             + REPLACE(REPLACE(REPLACE(CASE WHEN ISNULL(S.NOMBRE,'''') <> '''' THEN S.NOMBRE WHEN LEFT(S.COD, 2) = ''CO'' THEN S.DES ELSE S.DES + '' '' + ISNULL(CONVERT(VARCHAR(10), S.ORDEN), '''') END,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</option>''' + NCHAR(10) + N'        FROM #SV S' + NCHAR(10) + N'        OUTER APPLY (SELECT COUNT(*) AS N, SUM(A.HE) AS E, SUM(A.HT - A.HE) AS P, SUM(CASE WHEN A.SIT = ''e'' THEN 1 ELSE 0 END) AS NE,' + NCHAR(10) + N'                            SUM(CASE WHEN A.SIT = ''c'' THEN 1 ELSE 0 END) AS NC, SUM(CASE WHEN A.SIT NOT IN (''e'',''c'') THEN 1 ELSE 0 END) AS NPE' + NCHAR(10) + N'                     FROM #AGV A WHERE A.ID_PS = S.ID) X' + NCHAR(10) + N'        OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END) AS H, SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS NR,' + NCHAR(10) + N'                            SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END) AS NP' + NCHAR(10) + N'                     FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) INNER JOIN #AGV A2 ON A2.ID = D.ID_VISITA WHERE @AG_DES_ON = 1 AND A2.ID_PS = S.ID) DV' + NCHAR(10) + N'        WHERE ISNULL(X.N, 0) > 0' + NCHAR(10) + N'        ORDER BY CASE LEFT(S.COD, 2) WHEN ''CO'' THEN 1 WHEN ''AU'' THEN 2 WHEN ''CA'' THEN 3 ELSE 9 END, S.INI, S.ID' + NCHAR(10) + N'        FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'    SELECT @AG_CHIPS = ''<div class="vct-pv-acchips vct-pv-agchips" data-pv-agchips><button type="button" class="vct-pv-acchip is-on" data-pv-agchip="">Todos<i>'' + CONVERT(VARCHAR(10), @AG_NV) + ''</i></button>''' + NCHAR(10) + N'        + ISNULL((SELECT ''<button type="button" class="vct-pv-acchip'' + CASE WHEN ISNULL(X.N, 0) = 0 THEN '' is-zero'' ELSE '''' END + ''" data-pv-agchip="'' + LOWER(T.T) + ''">''' + NCHAR(10) + N'                        + CASE T.T WHEN ''CO'' THEN ''Consultor&iacute;a'' WHEN ''AU'' THEN ''Auditor&iacute;as'' WHEN ''CA'' THEN ''Capacitaciones'' ELSE REPLACE(REPLACE(REPLACE(T.DES,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') END + ''<i>'' + CONVERT(VARCHAR(10), ISNULL(X.N, 0)) + ''</i></button>''' + NCHAR(10) + N'                  FROM #SVT T OUTER APPLY (SELECT COUNT(*) AS N FROM #AGV A WHERE A.T = T.T) X ORDER BY T.ORD' + NCHAR(10) + N'                  FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''') + ''</div>'';' + NCHAR(10) + N'    IF @AG_DES_ON = 1' + NCHAR(10) + N'    BEGIN' + NCHAR(10) + N'        SELECT @AG_DHV = ISNULL(SUM(A.HE), 0), @AG_DNV = COUNT(*) FROM #AGV A WHERE A.T = ''CO'';' + NCHAR(10) + N'        SELECT @AG_DES_N = COUNT(*), @AG_DHR = ISNULL(SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END), 0),' + NCHAR(10) + N'               @AG_DNP = ISNULL(SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END), 0),' + NCHAR(10) + N'               @AG_DNVD = COUNT(DISTINCT CASE WHEN D.TIPO = ''REALIZADO'' THEN D.ID_VISITA END)' + NCHAR(10) + N'        FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) INNER JOIN #AGV A ON A.ID = D.ID_VISITA;' + NCHAR(10) + N'        SELECT @AG_DPROX = MIN(A.DESDE) FROM #AGV A WHERE A.DESDE > @HOY' + NCHAR(10) + N'          AND EXISTS (SELECT 1 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID AND D.TIPO = ''PLANIFICADO'');' + NCHAR(10) + N'        SELECT @AG_DCONS = ISNULL((SELECT ''<option value="'' + CONVERT(VARCHAR(20), Q.ID_CONSULTOR) + ''">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</option>''' + NCHAR(10) + N'            FROM (SELECT DISTINCT D.ID_CONSULTOR FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) INNER JOIN #AGV A ON A.ID = D.ID_VISITA) Q' + NCHAR(10) + N'            OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = Q.ID_CONSULTOR) Y' + NCHAR(10) + N'            ORDER BY Y.NOM FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        SELECT @AG_DINST_N = COUNT(*) FROM #SV S WHERE LEFT(S.COD, 2) = ''CO'';' + NCHAR(10) + N'        SELECT @AG_DINST = ISNULL((SELECT ''<option value="'' + CONVERT(VARCHAR(20), S.ID) + ''">'' + REPLACE(REPLACE(REPLACE(CASE WHEN ISNULL(S.NOMBRE,'''') <> '''' THEN S.NOMBRE WHEN LEFT(S.COD, 2) = ''CO'' THEN S.DES ELSE S.DES + '' '' + ISNULL(CONVERT(VARCHAR(10), S.ORDEN), '''') END,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</option>''' + NCHAR(10) + N'            FROM #SV S WHERE LEFT(S.COD, 2) = ''CO'' ORDER BY S.INI, S.ID FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        SELECT @AG_DES_ROWS = ISNULL((' + NCHAR(10) + N'            SELECT CONVERT(VARCHAR(MAX), '''') + ''<tr data-vct-row data-vct-filter-tipo="'' + CASE WHEN D.TIPO = ''REALIZADO'' THEN ''re'' ELSE ''pl'' END + ''"''' + NCHAR(10) + N'                 + '' data-vct-filter-cons="'' + CONVERT(VARCHAR(20), D.ID_CONSULTOR) + ''" data-vct-filter-inst="'' + CONVERT(VARCHAR(20), A.ID_PS) + ''"''' + NCHAR(10) + N'                 + '' data-vct-search="'' + LOWER(REPLACE(REPLACE(REPLACE(REPLACE(D.TITULO + '' '' + ISNULL(LEFT(D.DESARROLLO, 400), '''') + '' '' + ISNULL(I.CODIGO_ITEM, '''') + '' '' + ISNULL(I.TITULO, '''') + '' '' + ISNULL(Y.NOM, ''''),''&'',''&amp;''),''"'',''''),''<'',''''),''>'','''')) + ''">''' + NCHAR(10) + N'                 + ''<td data-vct-sort-value="'' + CONVERT(VARCHAR(8), A.DESDE, 112) + ''"><span class="vct-360-project-name">'' + CONVERT(VARCHAR(10), A.DESDE, 103) + ''</span><span class="vct-360-project-ref">'' + REPLACE(REPLACE(REPLACE(A.INST,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span></td>''' + NCHAR(10) + N'                 + ''<td>'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN ''<span class="vct-pl-code">'' + REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span> '' ELSE '''' END' + NCHAR(10) + N'                 + ''<span class="vct-360-project-ref">'' + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                 + ''<span class="vct-360-project-ref">Acci&oacute;n: '' + REPLACE(REPLACE(REPLACE(CASE WHEN ISNULL(CONVERT(VARCHAR(300), AC.DESCRIPCION), '''') <> '''' THEN CONVERT(VARCHAR(300), AC.DESCRIPCION) ELSE ISNULL(AC.TITULO, '''') END,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span></td>''' + NCHAR(10) + N'                 + ''<td><span class="vct-360-project-name">'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                 + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<span class="vct-360-project-ref">'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 400),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>'' ELSE '''' END' + NCHAR(10) + N'                 + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN ''<span class="vct-360-project-ref vct-pv-agd-nx">Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>'' ELSE '''' END + ''</td>''' + NCHAR(10) + N'                 + ''<td class="vct-text-center" data-vct-export-value="'' + CASE WHEN D.TIPO = ''REALIZADO'' THEN ''Realizado'' ELSE ''Planificado'' END + ''"><span class="vct-pl-tp '' + CASE WHEN D.TIPO = ''REALIZADO'' THEN ''is-re">Realizado'' ELSE ''is-pl">Planificado'' END + ''</span></td>''' + NCHAR(10) + N'                 + ''<td data-vct-export-value="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''"><span class="vct-pv-agd-who"><span class="vctdg-avatar is-c" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + ISNULL(Y.INI, '''') + ''</span>'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span></td>''' + NCHAR(10) + N'                 + ''<td class="vct-text-right" data-vct-sort-value="'' + CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(D.HORAS, 0))) + ''">'' + CASE WHEN D.TIPO = ''REALIZADO'' THEN REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + '' h'' ELSE ''&ndash;'' END + ''</td>''' + NCHAR(10) + N'                 + ''<td class="vct-table-action-cell" data-vct-export-ignore="true">'' + ''<button type="button" class="vct-row-menu-trigger" data-vctdg-rowmenu aria-label="Acciones" title="Acciones"><span class="vct-row-menu-dots" aria-hidden="true">&#8942;</span></button>'' + ''<div class="vctdg-rowmenu-items" hidden>''' + NCHAR(10) + N'                 + ''<button type="button" class="vct-pv-menu-btn" data-pv-agw-open="'' + CONVERT(VARCHAR(20), A.ID) + ''"><span data-vct-icon="eye"></span><span>Trabajo de la visita</span></button></div></td></tr>''' + NCHAR(10) + N'            FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'            INNER JOIN #AGV A ON A.ID = D.ID_VISITA' + NCHAR(10) + N'            INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'            LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'            OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM, UPPER(LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),'''')),1) + LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''')),1)) AS INI FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'            ORDER BY A.DESDE DESC, I.ORDEN, D.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        SET @AG_DES_H = CONVERT(VARCHAR(MAX), '''') + ''<div data-pv-agpane="des" hidden>''' + NCHAR(10) + N'            + ''<div class="vct-360-stats-row vct-pv-agd-stats">''' + NCHAR(10) + N'            + ''<div class="vct-360-stat" data-vct-tone="blue"><span class="vct-360-stat-main"><span class="vct-360-stat-label">Horas de visita</span><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(@AG_DHV, 0))), ''.0'', '''') + '' h'' + ''</b><small>'' + CONVERT(VARCHAR(10), @AG_DNV) + '' visita(s) de consultor&iacute;a &middot; '' + CONVERT(VARCHAR(10), @AG_DNVD) + '' con desarrollo'' + ''</small></span><span class="vct-360-stat-icon"><span data-vct-icon="clock-3"></span></span></div>''' + NCHAR(10) + N'            + ''<div class="vct-360-stat" data-vct-tone="mint"><span class="vct-360-stat-main"><span class="vct-360-stat-label">Volcadas en desarrollos</span><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(@AG_DHR, 0))), ''.0'', '''') + '' h'' + ''</b><small>'' + CONVERT(VARCHAR(10), CASE WHEN @AG_DHV > 0 THEN CONVERT(INT, ROUND(@AG_DHR * 100.0 / @AG_DHV, 0)) ELSE 0 END) + '' % de las horas de visita'' + ''</small></span><span class="vct-360-stat-icon"><span data-vct-icon="check"></span></span></div>''' + NCHAR(10) + N'            + ''<div class="vct-360-stat" data-vct-tone="amber"><span class="vct-360-stat-main"><span class="vct-360-stat-label">Sin detallar</span><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(CASE WHEN @AG_DHV > @AG_DHR THEN @AG_DHV - @AG_DHR ELSE 0 END, 0))), ''.0'', '''') + '' h'' + ''</b><small>'' + ''dato de informe'' + ''</small></span><span class="vct-360-stat-icon"><span data-vct-icon="clipboard-check"></span></span></div>''' + NCHAR(10) + N'            + ''<div class="vct-360-stat" data-vct-tone="violet"><span class="vct-360-stat-main"><span class="vct-360-stat-label">Planificados</span><b>'' + CONVERT(VARCHAR(10), @AG_DNP) + ''</b><small>'' + CASE WHEN @AG_DPROX IS NULL THEN ''sin pr&oacute;xima visita con planificados'' ELSE ''pr&oacute;xima visita '' + CONVERT(VARCHAR(5), @AG_DPROX, 103) END + ''</small></span><span class="vct-360-stat-icon"><span data-vct-icon="list-checks"></span></span></div>''' + NCHAR(10) + N'            + ''</div>''' + NCHAR(10) + N'            + ''<div data-vct-dg data-vct-dg-id="pv_agdes" data-vct-dg-title="Desarrollo de las visitas" data-vct-dg-subtitle="Proyecto ('' + @E_COD + '')" data-vct-dg-unit="registro(s)" data-vct-dg-page-size="10"''' + NCHAR(10) + N'            + '' data-vct-dg-search-placeholder="Buscar desarrollo, &iacute;tem o consultor..." data-vct-dg-density="compact" data-vct-dg-layout="fixed">''' + NCHAR(10) + N'            + ''<div data-vct-dg-slot="filters"><select data-vct-dg-filter="tipo" aria-label="Tipo"><option value="">Tipo</option><option value="re">Realizado</option><option value="pl">Planificado</option></select>''' + NCHAR(10) + N'            + ''<select data-vct-dg-filter="cons" aria-label="Consultor"><option value="">Consultor</option>'' + @AG_DCONS + ''</select>''' + NCHAR(10) + N'            + CASE WHEN @AG_DINST_N > 1 THEN ''<select data-vct-dg-filter="inst" aria-label="Servicio"><option value="">Servicio</option>'' + @AG_DINST + ''</select>'' ELSE '''' END + ''</div>''' + NCHAR(10) + N'            + ''<table><thead><tr><th data-vct-width="130" data-vct-sortable="true" data-vct-sort-type="number"><span>Visita</span></th>''' + NCHAR(10) + N'            + ''<th data-vct-width="22%"><span>&Iacute;tem / acci&oacute;n</span></th><th><span>Desarrollo</span></th>''' + NCHAR(10) + N'            + ''<th class="vct-text-center" data-vct-width="110"><span>Tipo</span></th><th data-vct-width="170"><span>Consultor</span></th>''' + NCHAR(10) + N'            + ''<th class="vct-text-right" data-vct-width="70" data-vct-sortable="true" data-vct-sort-type="number"><span>Horas</span></th>''' + NCHAR(10) + N'            + ''<th class="vct-col-action" data-vct-width="48" data-vct-export-ignore="true"></th></tr></thead><tbody>'' + @AG_DES_ROWS + ''</tbody></table></div></div>'';' + NCHAR(10) + N'    END;' + NCHAR(10) + N'    SET @AG_H = CONVERT(VARCHAR(MAX), '''')' + NCHAR(10);
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' calc'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* vis_apply */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'        FROM #AGV A' + NCHAR(10) + N'        ORDER BY CASE A.T WHEN ''CO'' THEN 1 WHEN ''AU'' THEN 2 WHEN ''CA'' THEN 3 ELSE 9 END, A.DESDE, A.ID';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'        FROM #AGV A' + NCHAR(10) + N'        OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END) AS H, SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS NR,' + NCHAR(10) + N'                            SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END) AS NP' + NCHAR(10) + N'                     FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE A.T = ''CO'' AND D.ID_VISITA = A.ID) DV   /* VIS_SRV_V1 */' + NCHAR(10) + N'        ORDER BY CASE A.T WHEN ''CO'' THEN 1 WHEN ''AU'' THEN 2 WHEN ''CA'' THEN 3 ELSE 9 END, A.DESDE, A.ID';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' vis_apply'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* vis_inst */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'data-vct-filter-servicio="'' + LOWER(A.T) + ''" data-vct-filter-estado';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'data-vct-filter-servicio="'' + LOWER(A.T) + ''" data-vct-filter-inst="'' + CONVERT(VARCHAR(20), A.ID_PS) + ''" data-vct-filter-estado';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' vis_inst'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* vis_cell */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'             +   ''<span class="vct-360-project-ref">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), A.HT - A.HE)), ''.0'', '''') + '' h programadas</span></td>''' + NCHAR(10);
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'             +   ''<span class="vct-360-project-ref">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), A.HT - A.HE)), ''.0'', '''') + '' h programadas</span></td>''' + NCHAR(10) + N'             + ''<td class="vct-text-center" data-vct-export-value="'' + CASE WHEN ISNULL(DV.NR, 0) > 0 THEN REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(DV.H, 0))), ''.0'', '''') + '' h / '' + CONVERT(VARCHAR(10), DV.NR) + '' reg.'' WHEN ISNULL(DV.NP, 0) > 0 THEN CONVERT(VARCHAR(10), DV.NP) + '' planificado(s)'' ELSE ''-'' END + ''">''' + NCHAR(10) + N'             +   CASE WHEN ISNULL(DV.NR, 0) > 0 THEN ''<button type="button" class="vct-pl-dchip" data-pv-agw-open="'' + CONVERT(VARCHAR(20), A.ID) + ''" title="Trabajo de la visita">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(18,1), ISNULL(DV.H, 0))), ''.0'', '''') + '' h &middot; '' + CONVERT(VARCHAR(10), DV.NR) + '' reg.''' + NCHAR(10) + N'                                 + CASE WHEN ISNULL(DV.NP, 0) > 0 THEN '' &middot; '' + CONVERT(VARCHAR(10), DV.NP) + '' planif.'' ELSE '''' END + ''</button>''' + NCHAR(10) + N'                       WHEN ISNULL(DV.NP, 0) > 0 THEN ''<button type="button" class="vct-pl-dchip is-pl" data-pv-agw-open="'' + CONVERT(VARCHAR(20), A.ID) + ''" title="Trabajo de la visita">'' + CONVERT(VARCHAR(10), DV.NP) + '' planificado'' + CASE WHEN DV.NP = 1 THEN '''' ELSE ''s'' END + ''</button>''' + NCHAR(10) + N'                       ELSE ''<span class="vctdg-none">-</span>'' END + ''</td>''' + NCHAR(10);
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' vis_cell'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* vis_th */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<th class="vct-text-center" data-vct-width="110"><span>Estado</span></th><th data-vct-width="18%"><span>Log&iacute;stica</span></th>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<th class="vct-text-center" data-vct-width="130"><span>Desarrollos</span></th>''' + NCHAR(10) + N'        + ''<th class="vct-text-center" data-vct-width="110"><span>Estado</span></th><th data-vct-width="14%"><span>Log&iacute;stica</span></th>''';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' vis_th'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* vis_filtro */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<select data-vct-dg-filter="servicio" aria-label="Servicio"><option value="">Servicio</option>'' + @AG_FSRV + ''</select></div>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<select data-vct-dg-filter="servicio" aria-label="Tipo de servicio" data-pv-agtsel><option value="">Tipo de servicio</option>'' + @AG_FSRV + ''</select>''' + NCHAR(10) + N'        + ''<select data-vct-dg-filter="inst" aria-label="Servicio" data-pv-aginst><option value="">Servicio (todos)</option>'' + @AG_FINST + ''</select></div>''';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' vis_filtro'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* vis_btn */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<button type="button" data-pv-agv="cal">'' + @AG_IC_C + ''<span>Calendario</span></button></div></div>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<button type="button" data-pv-agv="cal">'' + @AG_IC_C + ''<span>Calendario</span></button>''' + NCHAR(10) + N'        + CASE WHEN @AG_DES_ON = 1 THEN ''<button type="button" data-pv-agv="des">'' + @AG_IC_D + ''<span>Desarrollo</span><i class="vct-pv-agv-n">'' + CONVERT(VARCHAR(10), @AG_DES_N) + ''</i></button>'' ELSE '''' END + ''</div></div>''';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' vis_btn'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* vis_chips */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<div data-pv-agpane="lista">''' + NCHAR(10);
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<div data-pv-agpane="lista">'' + @AG_CHIPS + ''<div class="vct-360-stats-row vct-pv-agsum" data-pv-agsum hidden></div>''' + NCHAR(10);
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' vis_chips'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* vis_des */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'+ '' data-pv-agevt="'' + REPLACE(REPLACE(REPLACE(@AG_EVT,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;'') + ''"></div></div>''' + NCHAR(10) + N'        + ''</div></div>'';';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'+ '' data-pv-agevt="'' + REPLACE(REPLACE(REPLACE(@AG_EVT,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;'') + ''"></div></div>''' + NCHAR(10) + N'        + @AG_DES_H' + NCHAR(10) + N'        + ''</div></div>'';';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' vis_des'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* assets */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'vct-proyecto-v360.css?v=47"><script src="../js/vct-proyecto-v360.js?v=39"';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'vct-proyecto-v360.css?v=48"><script src="../js/vct-proyecto-v360.js?v=40"';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' assets'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    IF @F <> N''
        PRINT 'FALLO: no se encontraron (o estan repetidos) en la definicion vigente los puntos:' + @F + '. No se cambio nada.';
    ELSE
    BEGIN
        SET @s = CHARINDEX(N'PROCEDURE', @D);
        SET @p = CASE WHEN @s > 40 THEN @s - 40 ELSE 1 END;
        IF CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) > 0 AND CHARINDEX(N'OR ALTER', SUBSTRING(@D, @p, 40)) = 0
            SET @D = STUFF(@D, @p + CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) - 1, 6, N'ALTER ');
        BEGIN TRY
            EXEC sys.sp_executesql @D;
            PRINT 'OK   VCT_MAIN_PROYECTO_V360 actualizado (VIS_SRV_V1). Subir vct-proyecto-v360.css (v48) y vct-proyecto-v360.js (v40).';
        END TRY
        BEGIN CATCH
            PRINT 'FALLO al actualizar dbo.VCT_MAIN_PROYECTO_V360 (no se cambio): ' + ERROR_MESSAGE() + ' (linea ' + CONVERT(VARCHAR(10), ERROR_LINE()) + ')';
        END CATCH;
    END;
END;
GO
